54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private final ClinicService clinicService;
64	
65	    private final OwnerMapper ownerMapper;
66	
67	    private final PetMapper petMapper;
68	
69	    private final VisitMapper visitMapper;
70	
71	    private final OwnerFieldsValidator ownerFieldsValidator;
72	
73	    private final TelephoneNormalizer telephoneNormalizer;
74	
75	    private final EmailNormalizer emailNormalizer;
76	
77	    private final HouseholdDuplicateValidator householdDuplicateValidator;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper,
83	                                 OwnerFieldsValidator ownerFieldsValidator,
84	                                 TelephoneNormalizer telephoneNormalizer,
85	                                 EmailNormalizer emailNormalizer,
86	                                 HouseholdDuplicateValidator householdDuplicateValidator) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	        this.ownerFieldsValidator = ownerFieldsValidator;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.emailNormalizer = emailNormalizer;
94	        this.householdDuplicateValidator = householdDuplicateValidator;
95	    }
96	
97	    /**
98	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
99	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
100	     */
101	    @InitBinder("ownerFieldsDto")
102	    void initOwnerFieldsBinder(WebDataBinder binder) {
103	        binder.addValidators(ownerFieldsValidator);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
109	        Collection<Owner> owners;
110	        if (lastName != null) {
111	            owners = this.clinicService.findOwnerByLastName(lastName);
112	        } else {
113	            owners = this.clinicService.findAllOwners();
114	        }
115	        if (owners.isEmpty()) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
124	        Owner owner = this.clinicService.findOwnerById(ownerId);
125	        if (owner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        HttpHeaders headers = new HttpHeaders();
135	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
136	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
137	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
138	            throw new DuplicateTelephoneException(telephone);
139	        }
140	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
141	            householdDuplicateValidator.validate(owner);
142	        }
143	        owner.setTelephone(telephone);
144	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
145	        this.clinicService.saveOwner(owner);
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        headers.setLocation(UriComponentsBuilder.newInstance()
148	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
149	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Override
154	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
155	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
156	        if (currentOwner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        currentOwner.setAddress(ownerFieldsDto.getAddress());
160	        currentOwner.setCity(ownerFieldsDto.getCity());
161	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
162	        currentOwner.setLastName(ownerFieldsDto.getLastName());
163	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
164	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
165	        this.clinicService.saveOwner(currentOwner);
166	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Transactional
171	    @Override
172	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        this.clinicService.deleteOwner(owner);
178	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        HttpHeaders headers = new HttpHeaders();
189	        Pet pet = petMapper.toPet(petFieldsDto);
190	        owner.setId(ownerId);
191	        pet.setOwner(owner);
192	        pet.getType().setName(null);
193	        this.clinicService.savePet(pet);
194	        PetDto petDto = petMapper.toPetDto(pet);
195	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
196	            .buildAndExpand(pet.getId()).toUri());
197	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
203	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
204	        if (currentOwner != null) {
205	            Pet currentPet = this.clinicService.findPetById(petId);
206	            if (currentPet != null) {
207	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
208	                currentPet.setName(petFieldsDto.getName());
209	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
210	                this.clinicService.savePet(currentPet);
211	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
212	            }
213	        }
214	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	    }
216	
217	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
218	    @Override
219	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
220	        HttpHeaders headers = new HttpHeaders();
221	        Visit visit = visitMapper.toVisit(visitFieldsDto);
222	        Pet pet = new Pet();
223	        pet.setId(petId);
224	        visit.setPet(pet);
225	        this.clinicService.saveVisit(visit);
226	        VisitDto visitDto = visitMapper.toVisitDto(visit);
227	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
228	            .buildAndExpand(visit.getId()).toUri());
229	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
230	    }
231	
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner != null) {
238	            Pet pet = owner.getPet(petId);
239	            if (pet != null) {
240	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
241	            }
242	        }
243	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	    }
245	}
