18	
19	import java.util.regex.Pattern;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Normalizes a raw telephone input into canonical E.164 form.
25	 * <p>
26	 * Spaces, dashes and brackets are stripped. When the remaining value carries a
27	 * leading {@code '+'} its country code is kept as supplied; otherwise the default
28	 * country code {@link #DEFAULT_COUNTRY_CODE} is assumed and a single leading
29	 * {@code '0'} is dropped from the national digits. The digits following the
30	 * {@code '+'} must number between {@link #MIN_DIGITS} and {@link #MAX_DIGITS};
31	 * anything else is rejected with an {@link InvalidTelephoneException} (surfaced as
32	 * {@code 400 Bad Request}).
33	 */
34	@Component
35	public class TelephoneNormalizer {
36	
37	    private static final String DEFAULT_COUNTRY_CODE = "61";
38	    private static final int MIN_DIGITS = 8;
39	    private static final int MAX_DIGITS = 15;
40	
41	    /** Matches the digits that must follow the '+' once the country code is resolved. */
42	    private static final Pattern E164_DIGITS =
43	        Pattern.compile("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}");
44	
45	    /**
46	     * Convert {@code rawTelephone} into its E.164 representation.
47	     *
48	     * @param rawTelephone the telephone as supplied by the client (may contain formatting)
49	     * @return the E.164 telephone (a leading {@code '+'} followed by 8-15 digits) to store and return
50	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
51	     */
52	    public String normalize(String rawTelephone) {
53	        String cleaned = rawTelephone == null ? "" : rawTelephone.replaceAll("[\\s()-]", "");
54	        String digits;
55	        if (cleaned.startsWith("+")) {
56	            digits = cleaned.substring(1);
57	        } else {
58	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
59	            digits = DEFAULT_COUNTRY_CODE + national;
60	        }
61	        if (!E164_DIGITS.matcher(digits).matches()) {
62	            throw new InvalidTelephoneException(rawTelephone);
63	        }
64	        return "+" + digits;
65	    }
66	}
