18	
19	import java.util.Locale;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.service.ClinicService;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Guards owner creation against duplicate households: two owners are considered to share a
27	 * household when their last name and address match once compared case-insensitively and with
28	 * runs of whitespace collapsed to a single space.
29	 */
30	@Component
31	public class HouseholdDuplicateValidator {
32	
33	    private final ClinicService clinicService;
34	
35	    public HouseholdDuplicateValidator(ClinicService clinicService) {
36	        this.clinicService = clinicService;
37	    }
38	
39	    /**
40	     * Reject {@code candidate} when an existing owner already occupies the same household.
41	     *
42	     * @param candidate the owner about to be created
43	     * @throws DuplicateHouseholdException if another owner shares the candidate's last name and
44	     * address
45	     */
46	    public void validate(Owner candidate) {
47	        String lastNameKey = normalize(candidate.getLastName());
48	        String addressKey = normalize(candidate.getAddress());
49	        boolean duplicate = clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
50	            .anyMatch(existing -> lastNameKey.equals(normalize(existing.getLastName()))
51	                && addressKey.equals(normalize(existing.getAddress())));
52	        if (duplicate) {
53	            throw new DuplicateHouseholdException(candidate.getLastName(), candidate.getAddress());
54	        }
55	    }
56	
57	    /**
58	     * Canonicalize a value for household comparison: {@code null} becomes empty, surrounding
59	     * whitespace is trimmed, internal whitespace runs collapse to a single space, and the result
60	     * is lower-cased.
61	     */
62	    private String normalize(String value) {
63	        if (value == null) {
64	            return "";
65	        }
66	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
67	    }
68	}
