17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
33	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
34	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
35	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
36	import org.springframework.security.access.AccessDeniedException;
37	import org.springframework.validation.BindingResult;
38	import org.springframework.validation.FieldError;
39	import org.springframework.web.bind.MethodArgumentNotValidException;
40	import org.springframework.web.bind.annotation.ControllerAdvice;
41	import org.springframework.web.bind.annotation.ExceptionHandler;
42	import org.springframework.web.bind.annotation.ResponseBody;
43	
44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	    private static final String ERROR_DUPLICATE_TELEPHONE = "The telephone is already used by another owner";
60	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
61	
62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
79	
80	    /**
81	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
82	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
83	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
84	     * would catch it and report an authorization failure as a 500.
85	     *
86	     * @param e The {@link AccessDeniedException} to propagate
87	     * @throws AccessDeniedException always
88	     */
89	    @ExceptionHandler(AccessDeniedException.class)
90	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
91	        throw e;
92	    }
93	
94	    /**
95	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
96	     *
97	     * @param e The {@link Exception} to be handled
98	     * @param request {@link HttpServletRequest} object referring to the current request.
99	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
100	     */
101	    @ExceptionHandler(Exception.class)
102	    @ResponseBody
103	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
104	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
105	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
106	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
107	        return ResponseEntity.status(status).body(detail);
108	    }
109	
110	    /**
111	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
112	     * method returns a 404 Not Found status if an entity does not exist.
113	     *
114	     * @param e The {@link DataIntegrityViolationException} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
117	     */
118	    @ExceptionHandler(DataIntegrityViolationException.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
121	        logger.warn("Data integrity violation at {} {}: {}",
122	            request.getMethod(),
123	            request.getRequestURI(),
124	            e.getMessage());
125	        logger.debug("Data integrity violation stacktrace", e);
126	        HttpStatus status = HttpStatus.NOT_FOUND;
127	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
128	        return ResponseEntity.status(status).body(detail);
129	    }
130	
131	    /**
132	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone does not
133	     * reduce to exactly ten digits after non-digit characters are stripped.
134	     *
135	     * @param e The {@link InvalidTelephoneException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(InvalidTelephoneException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
144	        return ResponseEntity.status(status).body(detail);
145	    }
146	
147	    /**
148	     * Handles {@link DuplicateTelephoneException} raised when an owner is created with a
149	     * normalized telephone that another owner already uses.
150	     *
151	     * @param e The {@link DuplicateTelephoneException} to be handled
152	     * @param request {@link HttpServletRequest} object referring to the current request.
153	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
154	     */
155	    @ExceptionHandler(DuplicateTelephoneException.class)
156	    @ResponseBody
157	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
158	        HttpStatus status = HttpStatus.CONFLICT;
159	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
160	        return ResponseEntity.status(status).body(detail);
161	    }
162	
163	    /**
164	     * Handles {@link DuplicateHouseholdException} raised when an owner is created with a
165	     * last name and address that another owner already uses, without opting into a shared
166	     * household.
167	     *
168	     * @param e The {@link DuplicateHouseholdException} to be handled
169	     * @param request {@link HttpServletRequest} object referring to the current request.
170	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
171	     */
172	    @ExceptionHandler(DuplicateHouseholdException.class)
173	    @ResponseBody
174	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
175	        HttpStatus status = HttpStatus.CONFLICT;
176	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
177	        return ResponseEntity.status(status).body(detail);
178	    }
179	
180	    /**
181	     * Handles exception thrown by Bean Validation on controller methods parameters
182	     *
183	     * @param e The {@link MethodArgumentNotValidException} to be handled
184	     * @param request {@link HttpServletRequest} object referring to the current request.
185	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
186	     */
187	    @ExceptionHandler(MethodArgumentNotValidException.class)
188	    @ResponseBody
189	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
190	        HttpStatus status = HttpStatus.BAD_REQUEST;
191	        BindingErrorsResponse errors = new BindingErrorsResponse();
192	        BindingResult bindingResult = e.getBindingResult();
193	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
194	        if (bindingResult.hasErrors()) {
195	            errors.addAllErrors(bindingResult);
196	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
197	                .map(fieldError -> {
198	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
199	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
200	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
201	                        fieldError.getField(),
202	                        defaultMessage,
203	                        rejectedValue);
204	                    return new ValidationMessageDto(message)
205	                        .putAdditionalProperty("field", fieldError.getField())
206	                        .putAdditionalProperty("rejectedValue", rejectedValue)
207	                        .putAdditionalProperty("defaultMessage", defaultMessage);
208	                })
209	                .toList();
210	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
211	                .map(FieldError::getField)
212	                .distinct()
213	                .toList();
214	            logger.debug("Validation error at {} {}: {}",
215	                request.getMethod(),
216	                request.getRequestURI(),
217	                bindingResult.getFieldErrors());
218	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
219	            detail.setProperty("errors", invalidFields);
220	            return ResponseEntity.status(status).body(detail);
221	        }
222	        return ResponseEntity.status(status).body(detail);
223	    }
224	
225	}
